process.env.NODE_TLS_REJECT_UNAUTHORIZED='0';
const WP='https://dev.avesa.lt';
const AUTH='Basic '+Buffer.from((process.env.WP_USER||'').trim()+':'+(process.env.WP_APP_PASS||'').trim()).toString('base64');
const GH=process.env.GH_TOKEN, REPO=process.env.GH_REPO;
const KAT='';
const DEP=Buffer.from('','base64').toString();
async function putRaw(path,b64,msg){
  const url=`https://api.github.com/repos/${REPO}/contents/${path}`;
  let sha; try{ const r=await fetch(url,{headers:{Authorization:`Bearer ${GH}`}}); if(r.ok) sha=(await r.json()).sha; }catch(e){}
  const body={message:msg||'uxs6', content:b64}; if(sha) body.sha=sha;
  const pr=await fetch(url,{method:'PUT',headers:{Authorization:`Bearer ${GH}`,'Content-Type':'application/json'},body:JSON.stringify(body)});
  return pr.status;
}
const putJson=(p,o)=>putRaw(p, Buffer.from(JSON.stringify(o,null,2)).toString('base64'),'uxs6 json');
async function snip(name,code){
  const r=await fetch(`${WP}/wp-json/code-snippets/v1/snippets`,{method:'POST',
    headers:{Authorization:AUTH,'Content-Type':'application/json'},
    body:JSON.stringify({name, code, scope:'global', active:true})});
  return await r.json();
}
async function off(id){ await fetch(`${WP}/wp-json/code-snippets/v1/snippets/${id}`,{method:'POST',
  headers:{Authorization:AUTH,'Content-Type':'application/json'},body:JSON.stringify({active:false})}); }
const pause=ms=>new Promise(x=>setTimeout(x,ms));
async function main(){
  const out={VERSIJA:'UXS6'};
  let r=await fetch(`${WP}/wp-json/code-snippets/v1/snippets`,{headers:{Authorization:AUTH}});
  const list=await r.json();
  for(const t of (Array.isArray(list)?list:[]).filter(s=>s.active&&/^TEMP/i.test(s.name||''))){ await off(t.id); }
  let s=await snip('TEMP uxs6 set kat', "update_option('ps_uxd_kat','"+KAT+"','no');");
  await pause(2000); await fetch(`${WP}/`,{headers:{Authorization:AUTH}}); await off(s.id);
  const sd=await snip('TEMP uxs6 deploy', DEP.replace(/^<\?php\s*/,''));
  await pause(2500);
  let resp=await fetch(`${WP}/?ps_uxd2=1&k=dq7m3z`,{headers:{Authorization:AUTH}});
  try{ out.deploy=JSON.parse(await resp.text()); }catch(e){ out.deploy_raw='nejson'; }

  const {chromium}=await import('playwright');
  const br=await chromium.launch();
  const ctx=await br.newContext({ignoreHTTPSErrors:true, viewport:{width:1680,height:1050}});
  const page=await ctx.newPage();
  const jsErr=[]; page.on('pageerror',e=>jsErr.push(String(e)));
  page.on('dialog',async d=>{ out.dialogas=(d.message()||'').slice(0,150); await d.accept(); });

  await page.goto(`${WP}/?ps_uxlog2=1&k=dq7m3z`,{waitUntil:'networkidle',timeout:60000});
  await page.goto(`${WP}/wp-admin/admin.php?page=ps-katalogas&kruva=prekyboje&q=lamb&per=50`,{waitUntil:'networkidle',timeout:60000});
  await pause(1500);
  /* GILIAI nuscrollinam — blogiausias atvejis */
  await page.evaluate(()=>window.scrollTo(0, 1800));
  await pause(500);
  out.scrollY_pries=await page.evaluate(()=>window.scrollY);
  const eiles=await page.$$('.pskat-t tbody tr[data-id] a.atv');
  if(eiles.length>6){
    await eiles[6].click(); await pause(3500);
    out.scrollY_po=await page.evaluate(()=>window.scrollY);
    /* KRITINIS matavimas: ar kortelės viršus matomas ekrane */
    out.virsus=await page.evaluate(()=>{
      const k=document.getElementById('pskat-kort');
      const h=document.querySelector('.kort-pav-t');
      const img=document.querySelector('.kort-img');
      const kr=k.getBoundingClientRect();
      return {
        kortele_top:Math.round(kr.top), kortele_pos:getComputedStyle(k).position,
        pavadinimas_top: h?Math.round(h.getBoundingClientRect().top):null,
        pavadinimas_matomas: h?(h.getBoundingClientRect().top>0 && h.getBoundingClientRect().top<300):null,
        nuotrauka_matoma: img?(img.getBoundingClientRect().top>0):null,
        tekstas: h?h.textContent.trim().slice(0,45):null
      };
    });
    let png=await page.screenshot(); out.s_virsus=await putRaw('screenshots/uxs6_virsus.png', png.toString('base64'),'uxs6');

    /* PAVADINIMO keitimas — realus irasymas ir atstatymas */
    const pries=out.virsus.tekstas;
    await page.click('.kort-pav-keisti'); await pause(500);
    out.pav_laukas=await page.evaluate(()=>{ const r=document.querySelector('.kort-pav-red'); return r?!r.hidden:null; });
    await page.evaluate(()=>{ const t=document.querySelector('.kort-pav-in'); t.value=t.value+" TESTAS"; });
    await page.click('.kort-pav-irasyti'); await pause(2500);
    out.pav_po=await page.evaluate(()=>{
      const h=document.querySelector('.kort-pav-t');
      const a=document.querySelector('.pskat-t tbody tr.aktyvi a.atv');
      return {kortele:h?h.textContent.trim().slice(-25):null, sarase:a?a.textContent.trim().slice(-25):null,
              stat:(document.querySelector('.kort-pav-stat')||{}).textContent};
    });
    png=await page.screenshot(); out.s_pav=await putRaw('screenshots/uxs6_pavadinimas.png', png.toString('base64'),'uxs6 pav');
    /* atstatom */
    await page.click('.kort-pav-keisti'); await pause(400);
    await page.evaluate((p)=>{ document.querySelector('.kort-pav-in').value=p; }, pries);
    await page.click('.kort-pav-irasyti'); await pause(2500);
    out.pav_atstatyta=await page.evaluate(()=>{ const h=document.querySelector('.kort-pav-t'); return h?h.textContent.trim().slice(0,45):null; });

    /* SKU spyna */
    out.sku=await page.evaluate(()=>{
      const i=document.querySelector('.kort-sku input');
      return i?{readonly:i.readOnly, klase:i.className, atrakinti:!!document.querySelector('.kort-atrakinti')}:null;
    });
    await page.click('.kort-atrakinti'); await pause(900);
    out.sku_po_atrakinimo=await page.evaluate(()=>{
      const i=document.querySelector('.kort-sku input');
      return i?{readonly:i.readOnly, klase:i.className}:null;
    });
  }
  out.js_klaidos=jsErr.slice(0,8);
  await br.close(); await off(sd.id);
  r=await fetch(`${WP}/wp-json/code-snippets/v1/snippets`,{headers:{Authorization:AUTH}});
  const l2=await r.json();
  out.liko_temp=(Array.isArray(l2)?l2:[]).filter(x=>x.active&&/^TEMP/i.test(x.name||'')).map(x=>x.name);
  await putJson('analize/uxs6.json', out);
}
main().catch(async e=>{ await putJson('analize/uxs6.json',{klaida:String(e),stack:String(e&&e.stack).slice(0,700)}); });
